g.ns117:text:
% Optimal Transport Velocity
\begin{align*}
 % Transport plan
 &\tau_i=\frac{\mathrm{DPT}_i-\min_j \mathrm{DPT}_j}{\max_j \mathrm{DPT}_j-\min_j \mathrm{DPT}_j}\in[0,1]\\
 % Cost matrix
 &\text{Root: } \tau=0; \ \text{Terminal states: } \tau\approx1;
\end{align*}

% Optimal Transport Velocity
\begin{align*}
 % Transport plan
 \mathbf{P}^* &= \arg\min_{\mathbf{P} \in \Pi(\mathbf{a}, \mathbf{b})} 
 \langle \mathbf{P}, \mathbf{C} \rangle - \varepsilon \, H(\mathbf{P}) 
 \\[6pt]
 % Cost matrix
 C_{ij} &= \frac{\|\mathbf{x}_i - \mathbf{x}_j\|^2}{C_{\max}} 
 + \lambda_t \, \mathbb{1}[\tau_i > \tau_j] 
 + \lambda_k \, \mathbb{1}[j \notin \mathrm{KNN}(i)] 
\end{align*}
